INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(17772, 2, 0, 'plPL', 'Bądźcie czujni! Nadciąga kolejna fala.'),
(17852, 2, 0, 'plPL', 'Szykujcie się na kolejną falę! LOK-TAR OGAR!'),
(17852, 6, 0, 'plPL', 'Uraaa...');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(14697, 'plPL', '', 'Nie mam pojęcia, kim jesteś, ale twoja obecność jest jak najbardziej mile widziana. Archimond i jego armia Plagi mogą zaatakować w każdej chwili, $N. Czy staniesz z nami przeciwko temu złu?', 0),
(14698, 'plPL', 'Moi towarzysze i ja jesteśmy z tobą, lady Proudmoore.', 'Moi towarzysze i ja jesteśmy z tobą, lady Proudmoore.', 0),
(14699, 'plPL', '', 'Dziękuję. A teraz przygotujcie się. Archimond nadciąga, a my musimy jak najdłużej odwlekać to, co nieuniknione.', 0),
(14867, 'plPL', '$GNieznajomy:Nieznajoma;, pospiesz się i zgłoś do lady Jainy Proudmoore. Jej nieliczne siły Przymierza dzielnie próbują stępić pierwsze uderzenie Płonącego Legionu i opóźnić nadejście Archimonda.', '', 0),
(14869, 'plPL', 'Siły lady Proudmoore przelały krew, by opóźnić Archimonda i jego Płonący Legion, a teraz to ponure zadanie spada na nas. Czy jesteś $ggotów:gotowa; stanąć ze mną przeciw nawale?', '', 0),
(14875, 'plPL', 'Jestem z tobą, Thrallu.', 'Jestem z tobą, Thrallu.', 0),
(14877, 'plPL', 'Niech więc Legion robi, co w jego mocy!', '', 0),
(14990, 'plPL', 'Nareszcie nadeszła ta chwila! Opłakujcie i żałujcie wszystkiego, co kiedykolwiek znaliście, i wszystkiego, co mogło się wydarzyć! Hach min corai!', '', 0),
(14991, 'plPL', 'Nie, to niemożliwe! Nieee!', '', 0),
(15309, 'plPL', '', 'Zyskaliśmy cenny czas. Teraz musimy się wycofać.', 0),
(15310, 'plPL', '', '%s zaczyna splatać potężne zaklęcie teleportacji.', 0),
(15312, 'plPL', 'Odegraliśmy swoją rolę, i to dobrze. Teraz kolej na innych.', '', 0),
(15392, 'plPL', '', 'Dobra robota, $gposzukiwaczu:poszukiwaczko; przygód. Śmierć Rage\'a Zimowego Chłodu dała nam chwilę wytchnienia od natarcia wroga. Wykorzystaj ten krótki czas mądrze. Opatrz rannych i przygotuj obronę, bo Archimond wkrótce rzuci na nas jeszcze groźniejsze siły. Gdy bitwa znów się rozpocznie, wesprą cię moje skromne oddziały rezerwowe.', 0),
(15393, 'plPL', 'Jesteśmy gotowi na wszystko, co Archimond może na nas rzucić, lady Proudmoore.', 'Jesteśmy gotowi na wszystko, co Archimond może na nas rzucić, lady Proudmoore.', 0),
(15394, 'plPL', '', 'Niech więc Archimond robi, co w jego mocy.', 0),
(15415, 'plPL', '', 'Niesamowite! Pokonanie Anatherona z twojej ręki oddaliło Archimonda od celu i przybliżyło nas do zwycięstwa. Moje siły nie mogą jednak tu zostać. Moi żołnierze i ja jesteśmy wyczerpani, nadszedł czas odwrotu. Jeśli nie $gopadłeś:opadłaś; z sił, ruszaj na wschód, do obozowiska Thralla. Tam stawimy kolejny opór. Bywaj.', 0),
(15416, 'plPL', 'Do zobaczenia, lady Proudmoore.', 'Do zobaczenia, lady Proudmoore.', 0),
(15444, 'plPL', 'Znakomicie! Śmiertelny krzyk Kaz\'rogala powinien zasiać strach w samym sercu Płonącego Legionu. Wiedzą już, jaką moc mają twoje siły, więc spodziewaj się najgorszego, co Legion może przygotować.', '', 0),
(15445, 'plPL', 'Nie mamy się czego bać.', 'Nie mamy się czego bać.', 0),
(15448, 'plPL', 'Znakomicie! Zabicie lorda otchłani takiego jak Azgalor to nie lada wyczyn, przyjacielu. Gdybyśmy mieli więcej czasu, z chęcią wysłuchałbym opowieści o tobie i twoich towarzyszach. Archimond nie da nam jednak wytchnienia. Moi zwiadowcy donoszą już, że Legion gromadzi ogromne siły pod naszym obozem, a Archimond jest bardzo blisko Drzewa Świata. Ewakuujemy się z pomocą lady Proudmoore. Ty natychmiast udaj się do Drzewa Świata. Los naszego świata wciąż się waży.', '', 0),
(15449, 'plPL', 'Do zobaczenia, Thrallu.', 'Do zobaczenia, Thrallu.', 0),
(15497, 'plPL', '', 'Twoja pomoc w walce z Płonącym Legionem byłaby bardzo cenna. Lady Jainie Proudmoore przydałaby się twoja pomoc na pierwszej linii.', 0),
(15498, 'plPL', '', 'Twoja dalsza pomoc w walce z Płonącym Legionem wciąż byłaby bardzo cenna. Thrallowi przydałaby się twoja pomoc w jego obozowisku na zachód stąd.', 0),
(15499, 'plPL', '', 'Nadeszła chwila, której tak się obawialiśmy, $N. Archimond dotarł do Nordrassilu i zaczyna pożerać energię Drzewa Świata. Malfurion potrzebuje więcej czasu, by jego plan się powiódł, więc musimy zrobić rzecz nie do pomyślenia. Musisz zaatakować Archimonda bezpośrednio, a moi żołnierze powstrzymają strumienie sił Płonącego Legionu nadciągające na szczyt góry.', 0),
(15512, 'plPL', '', 'Gratulacje! Odnieśliśmy dziś wielkie zwycięstwo.', 0),
(18257, 'plPL', 'Wasz opór jest bez znaczenia.', '', 0),
(18261, 'plPL', 'Precz, robactwo!', '', 0),
(18262, 'plPL', 'Ten świat spłonie!', '', 0),
(18263, 'plPL', 'Manach sheek-thrish!', '', 0),
(18264, 'plPL', 'Twoja dusza będzie marnieć przez wieczność.', '', 0),
(18265, 'plPL', 'Całe stworzenie zostanie pożarte.', '', 0),
(18266, 'plPL', 'Jestem nadejściem końca!', '', 0),
(18537, 'plPL', '', 'Jestem w niebezpieczeństwie! Pomóżcie mi, jeśli możecie!', 0),
(18538, 'plPL', '', 'Przedarli się!', 0),
(18539, 'plPL', '', 'Zrobiłam... co mogłam.', 0),
(18540, 'plPL', '', 'Nie poddawajcie się! Musimy zwyciężyć!', 0),
(18541, 'plPL', '', 'Powstrzymajcie ich jak najdłużej!', 0),
(18542, 'plPL', '', 'Musimy wytrwać!', 0),
(18543, 'plPL', '', 'Jesteśmy zgubieni! Odwrót!', 0),
(18544, 'plPL', 'Przed nikim nie padnę!', '', 0),
(18545, 'plPL', 'Przyjdźcie do mnie walczyć i zapłaćcie życiem!', '', 0),
(18731, 'plPL', 'Powstrzymajcie ich! Nie wahajcie się!', '', 0),
(18733, 'plPL', 'Nie oddawajcie ani piędzi ziemi!', '', 0),
(18734, 'plPL', 'To koniec! Wycofać się! Ponieśliśmy klęskę...', '', 0),
(20242, 'plPL', 'Będę $gwdzięczny:wdzięczna; za każdą pomoc, jakiej możesz udzielić, kapłanko.', 'Będę $gwdzięczny:wdzięczna; za każdą pomoc, jakiej możesz udzielić, kapłanko.', 0),
(20243, 'plPL', '', 'Te Łzy Bogini zostały pobłogosławione przez Elune, a ich moc pomoże ci zwalczyć plugawą magię Archimonda. Wykorzystaj ją dobrze.', 0),
(20432, 'plPL', 'Wszystkie wasze wysiłki poszły na marne, bo wysysanie Drzewa Świata już się rozpoczęło! Wkrótce serce waszego świata przestanie bić!', '', 0),
(21645, 'plPL', 'To niebezpieczny tok myślenia. Gdyby naprawdę działo się coś złego, Soridormi dowiedziałaby się o tym pierwsza.', '', 0),
(21646, 'plPL', '', 'Myślisz, że pogłoski o Nieskończonym Stadzie są prawdziwe? Wyczułam to... tę znajomość.', 0);
